def is_valid(grid, pos, num):
    row, col = divmod(pos, 4)
    # Check row
    for i in range(4):
        if grid[row*4 + i] == num:
            return False
    # Check col
    for i in range(4):
        if grid[i*4 + col] == num:
            return False
    # Check block
    block_row, block_col = row//2 * 2, col//2 * 2
    for i in range(2):
        for j in range(2):
            if grid[(block_row+i)*4 + (block_col+j)] == num:
                return False
    return True

def solve(grid, pos=0):
    if pos == 16:
        return grid
    if grid[pos] != 0:
        return solve(grid, pos+1)
    for num in range(1,5):
        if is_valid(grid, pos, num):
            grid[pos] = num
            sol = solve(grid, pos+1)
            if sol:
                return sol
            grid[pos] = 0
    return None

grid = [0]*16
grid[7] = 2
grid[9] = 1
grid[12] = 4
solution = solve(grid)
print(solution)
